/* A deleted row can be put back. Whatever deletes a row from the tables that hold creators' and buyers' work and money (products and their files, variants and courses, orders, library entries, refunds, payouts, the balance and its history, plans and invoices, creators and profiles, OnePages, store and website settings and pages, domains and addresses, discount codes, email lists, flows and campaigns, reviews), whether a person, the app, a bug or a cascade, a copy of the row is kept first in public.deleted_rows, with the table, the row's id, when, and by which database role. public.storelib_restore_deleted_row(id) puts one back (ON CONFLICT DO NOTHING, so a row that exists again is left alone), and public.storelib_purge_deleted_rows() forgets copies older than 90 days, which the daily cron runs. This is the first layer under the backups (docs/operations/backups.md): an undo for the last three months, row by row, without restoring the whole database. Server and editor only. Safe to run again. */
CREATE TABLE IF NOT EXISTS public.deleted_rows (id bigserial PRIMARY KEY, table_name text NOT NULL, row_id text, row_data jsonb NOT NULL, deleted_at timestamptz NOT NULL DEFAULT now(), deleted_by text NOT NULL DEFAULT current_user, tx bigint NOT NULL DEFAULT txid_current());
CREATE INDEX IF NOT EXISTS deleted_rows_row_idx ON public.deleted_rows (table_name, row_id);
CREATE INDEX IF NOT EXISTS deleted_rows_when_idx ON public.deleted_rows (deleted_at);
CREATE INDEX IF NOT EXISTS deleted_rows_tx_idx ON public.deleted_rows (tx);
ALTER TABLE public.deleted_rows ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.deleted_rows FROM anon, authenticated;
CREATE OR REPLACE FUNCTION public.storelib_keep_deleted_row() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $f$ DECLARE j jsonb := to_jsonb(OLD); BEGIN INSERT INTO public.deleted_rows (table_name, row_id, row_data, deleted_by) VALUES (TG_TABLE_NAME, coalesce(j ->> 'id', j ->> 'creator_id', j ->> 'user_id'), j, session_user || '/' || current_setting('role', true)); RETURN OLD; END $f$;
REVOKE ALL ON FUNCTION public.storelib_keep_deleted_row() FROM PUBLIC, anon, authenticated;
DO $do$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['products', 'product_variants', 'product_variant_files', 'digital_assets', 'courses', 'orders', 'entitlements', 'refunds', 'payouts', 'ledger_events', 'seller_ledger', 'invoices', 'subscriptions', 'creators', 'profiles', 'onepages', 'store_builder_configs', 'store_theme_installs', 'sites', 'site_files', 'site_versions', 'site_collections', 'site_collection_items', 'site_forms', 'custom_domains', 'website_addresses', 'coupons', 'subscribers', 'email_flows', 'email_campaigns', 'email_templates', 'reviews'] LOOP IF to_regclass('public.' || t) IS NULL THEN CONTINUE; END IF; EXECUTE format('DROP TRIGGER IF EXISTS %I ON public.%I', t || '_keep_deleted', t); EXECUTE format('CREATE TRIGGER %I AFTER DELETE ON public.%I FOR EACH ROW EXECUTE FUNCTION public.storelib_keep_deleted_row()', t || '_keep_deleted', t); END LOOP; END $do$;
CREATE OR REPLACE FUNCTION public.storelib_restore_deleted_row(p_id bigint) RETURNS boolean LANGUAGE plpgsql SET search_path = public AS $f$ DECLARE r public.deleted_rows%ROWTYPE; n integer; BEGIN SELECT * INTO r FROM public.deleted_rows WHERE id = p_id; IF NOT FOUND OR to_regclass('public.' || r.table_name) IS NULL THEN RETURN false; END IF; EXECUTE format('INSERT INTO public.%I SELECT * FROM jsonb_populate_record(NULL::public.%I, $1) ON CONFLICT DO NOTHING', r.table_name, r.table_name) USING r.row_data; GET DIAGNOSTICS n = ROW_COUNT; RETURN n > 0; END $f$;
CREATE OR REPLACE FUNCTION public.storelib_purge_deleted_rows(p_keep interval DEFAULT interval '90 days') RETURNS integer LANGUAGE plpgsql SET search_path = public AS $f$ DECLARE n integer; BEGIN DELETE FROM public.deleted_rows WHERE id IN (SELECT id FROM public.deleted_rows WHERE deleted_at < now() - p_keep ORDER BY id LIMIT 50000); GET DIAGNOSTICS n = ROW_COUNT; RETURN n; END $f$;
REVOKE ALL ON FUNCTION public.storelib_restore_deleted_row(bigint) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.storelib_restore_deleted_row(bigint) TO service_role;
REVOKE ALL ON FUNCTION public.storelib_purge_deleted_rows(interval) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.storelib_purge_deleted_rows(interval) TO service_role;
notify pgrst, 'reload schema';
